index 8a498947..c7cedd05 100644
--- a/xinclude.c
+++ b/xinclude.c
@@ -1409,6 +1409,8 @@ xmlXIncludeLoadTxt(xmlXIncludeCtxtPtr ctxt, xmlXIncludeRefPtr ref) {
         xmlCtxtSetResourceLoader(pctxt, ctxt->resourceLoader,
